SELECT COUNT(*) FROM badges as b, comments as c, posts as p, postLinks as pl, votes as v, users as u WHERE c.UserId = u.Id AND p.Id = c.PostId AND b.UserId = u.Id AND p.Id = pl.RelatedPostId AND p.Id = v.PostId AND c.CreationDate>=CAST('2010-07-22 01:19:43' AS TIMESTAMP) AND p.Score>=-1 AND p.ViewCount>=0 AND p.CommentCount<=9 AND v.VoteTypeId=15
